function normalizeSchermaturaItem(value) {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  const item = value;
  const tipo = typeof item.tipo === "string" ? item.tipo : item.tipo_prodotto;
  const direzione = item.direzione;
  return {
    tipo: typeof tipo === "string" ? tipo : "",
    direzione: typeof direzione === "string" ? direzione : ""
  };
}
function normalizeProduct(value, fallback) {
  if (!value || typeof value !== "object" || Array.isArray(value)) return fallback;
  const product = value;
  const legacyItems = Array.isArray(product.schermature) ? product.schermature : [];
  const currentItems = Array.isArray(product.items) ? product.items : [];
  const items = (currentItems.length ? currentItems : legacyItems).map(normalizeSchermaturaItem).filter((item) => item !== null);
  if (product.tipo === "schermature" || items.length) return { tipo: "schermature", items };
  return value;
}
